import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.textanalytics import TextAnalyticsClient

client = TextAnalyticsClient(
    endpoint=os.environ["LANGUAGE_ENDPOINT"],
    credential=AzureKeyCredential(os.environ["LANGUAGE_KEY"]),
)
reviews = [
    "The screen is great but the battery is terrible.",
    "Call me on 555-0100. Delivery was fast!",
    "El hotel estaba limpio.",
]
for doc in client.analyze_sentiment(reviews, show_opinion_mining=True):
    if doc.is_error:
        print("Error:", doc.error.message)
        continue
    print(doc.sentiment, doc.confidence_scores)
    for sentence in doc.sentences:
        for opinion in sentence.mined_opinions:
            print("  ", opinion.target.text, opinion.target.sentiment)
for doc in client.recognize_pii_entities(reviews):
    print(doc.redacted_text)
for doc in client.detect_language(reviews):
    print(doc.primary_language.name, doc.primary_language.confidence_score)
